import { isJsonArray, isJsonObject, type Json, type JsonObject } from "@commissary/json";

/**
 * Golden translator cases (`test/fixtures/translator/`, generated by `tools/fixturegen/translator`) whose expectation
 * predates an upstream change Commissary has ported, by `<from>-><to> <case name>`. The fixture JSON stays untouched;
 * F2 (#388) regenerates it and deletes this module. Two mechanisms:
 *
 * - `portedMaxTokens` (ticket C2, Go `0d18d3b3`): the `max_tokens` a request case must now produce. A Chat Completions
 *   request without `max_tokens` gets the catalog's output limit for its model (the harness's `catalogLookup`) instead
 *   of the flat 32000 the fixtures recorded.
 * - `portedResponse` (ticket C3, Go `c449529e`, `9a7db8e3`, `6044c5d1`, `69637a66`): the OpenAI -> Claude response
 *   output a case must now produce. `stream` maps a response line index to the events it now emits (lines not listed
 *   keep their golden output); `nonStream` replaces the whole body. `message_delta` waits for the trailing usage-only
 *   chunk or `[DONE]` instead of firing on the chunk that carries `finish_reason`, and a top-level `reasoning_content`
 *   block precedes the text block.
 * - `portedChunkEdit` (ticket C6, Go `3f5d3a16`, `c5251b57`, `dfe0a0ef`): small edits to the golden stream chunks of the
 *   Gemini/Antigravity -> OpenAI Chat cases: Antigravity drops `delta.tool_calls: null`, a usage-only chunk keeps the
 *   stream's response id, and the parts of one chunk concatenate instead of the last overwriting the earlier ones.
 * - `portedRequestEdit` (ticket C6, Go `80aa2b1d`): the OpenAI -> Antigravity request of `tool_choice: "none"` keeps its
 *   `request.tools` (the fixture still drops them). (Ticket C7, Go `c558d320`): the Claude -> Gemini schema-cleaning
 *   cases inline the local `$ref` of a tool property instead of degrading it to a `See: Loc` hint.
 * - `portedParallelToolCalls` (ticket B2, Go `99d1698f`): the `parallel_tool_calls` a Codex-bound request case must now
 *   produce. An explicit `false` from the client survives instead of being forced to `true`; Go changed this case's
 *   input to `null` to keep covering the forced default, while the fixture still sends `false`.
 * - `portedRequestEdit` (ticket C8, Go `45501610`): the Gemini requests of the cases that mix built-in tools with function
 *   declarations (OpenAI Chat `google_search`; Responses `web_search`) carry `toolConfig.includeServerSideToolInvocations`.
 *   (Ticket C8, Go `c888ff72`): the Gemini -> OpenAI Chat request of a functionResponse-only turn drops the empty user
 *   message the fixture still keeps behind the tool messages.
 */

const ROWS: ReadonlyArray<readonly [string, number]> = [
  ["openai->claude request: images, files and cache control", 64000],
  ["openai->claude request: user turn with only an unsupported file is refused", 64000],
  ["openai->claude request: reasoning effort on a legacy budget model", 64000],
  ["openai->claude request: reasoning effort on an adaptive model", 128000],
  ["openai->claude request: reasoning effort none and auto", 128000],
  ["openai->claude request: reasoning effort auto", 128000],
  ["openai->claude request: allowed_tools choice filters tools", 64000],
  ["openai->claude request: function tool choice and response_format json_schema", 64000],
  ["openai->claude request: json_object format and none tool choice", 64000],
  ["openai->claude response: streamed thinking, text and tool calls", 64000],
  ["openai->claude response: non-stream message with tools and usage", 64000],
  ["openai->claude response: non-stream max_tokens", 64000],
  ["openai->claude response: non-stream refusal", 64000],
];

const PORTED_MAX_TOKENS_AHEAD_OF_FIXTURES: ReadonlyMap<string, number> = new Map(ROWS);

const used = new Set<string>();

/** The `max_tokens` the case `key` now produces, when its golden predates the port. */
export const portedMaxTokens = (key: string): number | undefined => {
  const maxTokens = PORTED_MAX_TOKENS_AHEAD_OF_FIXTURES.get(key);

  if (maxTokens !== undefined) used.add(key);

  return maxTokens;
};

/** The entries no case consumed: stale once the fixtures are regenerated or a case is renamed. */
export const unusedMaxTokensAheadEntries = (): string[] =>
  [...PORTED_MAX_TOKENS_AHEAD_OF_FIXTURES.keys()].filter((key) => !used.has(key));

const PORTED_PARALLEL_TOOL_CALLS_AHEAD_OF_FIXTURES: ReadonlyMap<string, boolean> = new Map([
  [
    "openai-response->codex request: string input, sampling and cache fields stripped, system role to developer",
    false,
  ],
]);

const usedParallel = new Set<string>();

/** The `parallel_tool_calls` the case `key` now produces, when its golden predates the port. */
export const portedParallelToolCalls = (key: string): boolean | undefined => {
  const value = PORTED_PARALLEL_TOOL_CALLS_AHEAD_OF_FIXTURES.get(key);

  if (value !== undefined) usedParallel.add(key);

  return value;
};

/** The entries no case consumed. */
export const unusedParallelToolCallsAheadEntries = (): string[] =>
  [...PORTED_PARALLEL_TOOL_CALLS_AHEAD_OF_FIXTURES.keys()].filter((key) => !usedParallel.has(key));

/** What a response case now produces; see the module comment. */
export interface PortedResponse {
  readonly stream?: ReadonlyMap<number, ReadonlyArray<string>>;
  readonly nonStream?: string;
}

const sse = (type: string, payload: JsonObject): string =>
  `event: ${type}\ndata: ${JSON.stringify(payload)}\n\n`;

const messageStop = sse("message_stop", { type: "message_stop" });

const messageDelta = (stopReason: string, usage: JsonObject): string =>
  sse("message_delta", {
    type: "message_delta",
    delta: { stop_reason: stopReason, stop_sequence: null },
    usage,
  });

