const PORTED_RESPONSES: ReadonlyMap<string, PortedResponse> = new Map(RESPONSE_ROWS);

const usedResponses = new Set<string>();

/** The response output the case `key` now produces, when its golden predates the C3 port. */
export const portedResponse = (key: string): PortedResponse | undefined => {
  const ported = PORTED_RESPONSES.get(key);

  if (ported !== undefined) usedResponses.add(key);

  return ported;
};

/** The response entries no case consumed: stale once the fixtures are regenerated or a case is renamed. */
export const unusedResponseAheadEntries = (): string[] =>
  [...PORTED_RESPONSES.keys()].filter((key) => !usedResponses.has(key));

/** An edit of one golden JSON value (a stream chunk or a request), applied in place. */
type GoldenEdit = (golden: JsonObject) => void;

const dropNullToolCalls: GoldenEdit = (chunk) => {
  const choices = chunk["choices"];

  if (!Array.isArray(choices)) return;

  for (const choice of choices) {
    const delta = isJsonObject(choice) ? choice["delta"] : undefined;

    if (isJsonObject(delta) && delta["tool_calls"] === null) delete delta["tool_calls"];
  }
};

/** Sets `value` at `path` (object keys and array indices) below the golden. */
const setPath =
  (path: ReadonlyArray<string | number>, value: Json): GoldenEdit =>
  (golden) => {
    let node: Json | undefined = golden;

    for (const key of path.slice(0, -1)) {
      node =
        typeof key === "number"
          ? isJsonArray(node)
            ? node[key]
            : undefined
          : isJsonObject(node)
            ? node[key]
            : undefined;
    }

    const last = path.at(-1);

    if (typeof last === "number" && isJsonArray(node)) node[last] = value;
    else if (typeof last === "string" && isJsonObject(node)) node[last] = value;
    else throw new Error(`ported-ahead edit: no container at ${path.join(".")}`);
  };

/** `line` -> edit; `"*"` edits every chunk of the case. */
type CaseChunkEdits = ReadonlyMap<number | "*", GoldenEdit>;

const CHUNK_EDIT_ROWS: ReadonlyArray<readonly [string, CaseChunkEdits]> = [
  ...[
    "stream: reasoning, text, images, tool calls and final usage",
    "stream: [DONE] synthesises the terminal chunk with pending usage",
    "stream: MAX_TOKENS and empty streams",
  ].map((name): readonly [string, CaseChunkEdits] => [
    `openai->antigravity ${name}`,
    new Map([["*", dropNullToolCalls]]),
  ]),
  [
    "openai->gemini stream: two candidates, max tokens, usage-only chunk and data prefix",
    new Map([[2, setPath(["id"], "multi")]]),
  ],
  [
    "openai->gemini stream: reasoning, text, tool calls, image output and final usage",
    new Map([[2, setPath(["choices", 0, "delta", "content"], "Hi there")]]),
  ],
];

const CHUNK_EDITS: ReadonlyMap<string, CaseChunkEdits> = new Map(CHUNK_EDIT_ROWS);

/** Edits that changed a golden: one that changes nothing is stale (the fixtures were regenerated). */
const effectiveEdits = new Set<string>();

/** Applies `edit` to the JSON `text` and reports whether the value changed. */
const applyEdit = (edit: GoldenEdit, text: string, key: string): string => {
  // SAFETY: the goldens edited here are JSON objects (stream chunks, requests); `edit` throws on any other shape.
  const parsed = JSON.parse(text) as JsonObject;
  const before = JSON.stringify(parsed);
  edit(parsed);
  const after = JSON.stringify(parsed);

  if (after !== before) effectiveEdits.add(key);

  return after;
};

/** The edit the golden chunk of `line` in case `key` needs, if its golden predates the C6 port. */
export const portedChunkEdit = (key: string, line: number): ((chunk: string) => string) => {
  const edits = CHUNK_EDITS.get(key);
  const edit = edits?.get(line) ?? edits?.get("*");

  if (edit === undefined) return (chunk) => chunk;

  return (chunk) =>
    chunk.startsWith("data:")
      ? `data: ${applyEdit(edit, chunk.slice(5).trim(), key)}`
      : applyEdit(edit, chunk, key);
};

/** The `loc` property of the `claude->gemini` schema-cleaning cases: its local `$ref` is inlined now (C7, `c558d320`). */
const inlinedLocRef: GoldenEdit = setPath(
  ["tools", 0, "functionDeclarations", 0, "parametersJsonSchema", "properties", "loc"],
  { type: "object", properties: { lat: { type: "number" } } },
);

/** Mixed built-in and function tools now declare `toolConfig.includeServerSideToolInvocations` (C8, `45501610`). */
const serverSideToolInvocations: GoldenEdit = (golden) => {
  const toolConfig = golden["toolConfig"];

  if (isJsonObject(toolConfig)) toolConfig["includeServerSideToolInvocations"] = true;
  else golden["toolConfig"] = { includeServerSideToolInvocations: true };
};

/** A functionResponse-only Gemini turn no longer leaves an empty `{role, content: ""}` message behind its tool messages (C8, `c888ff72`). */
const dropEmptyMessageAfterToolMessages: GoldenEdit = (golden) => {
  const messages = golden["messages"];

  if (!isJsonArray(messages)) return;

  golden["messages"] = messages.filter(
    (message, index) =>
      !(
        isJsonObject(message) &&
        message["content"] === "" &&
        message["role"] === "user" &&
        index > 0 &&
        isJsonObject(messages[index - 1]) &&
        (messages[index - 1] as JsonObject)["role"] === "tool"
      ),
  );
};

const REQUEST_EDITS: ReadonlyMap<string, GoldenEdit> = new Map([
  [
    "gemini->openai request: system, generation config, parts, tools and tool results",
    dropEmptyMessageAfterToolMessages,
  ],
  ...[
    "openai->gemini request: multimodal user turn, tool round trip, reasoning, structured output, modalities, builtin tools",
    "openai->gemini stream: reasoning, text, tool calls, image output and final usage",
    "openai->gemini non-stream: reasoning, text, tool call, image and a second candidate",
    "openai-response->gemini request: tools and tool_choice absent",
    'openai-response->gemini request: tools and tool_choice "auto"',
    'openai-response->gemini request: tools and tool_choice "required"',
  ].map((key): readonly [string, GoldenEdit] => [key, serverSideToolInvocations]),
  ...[
    "request: system, multimodal user turn, tool round trip, schema cleaning, strict tool choice, thinking budget",
    "stream: thinking with signature, text, two tool calls, usage and finish",
    "non-stream: thinking, text, tool calls, cached usage",
  ].map((name): readonly [string, GoldenEdit] => [`claude->gemini ${name}`, inlinedLocRef]),
  [
    "openai->antigravity request: tool_choice none removes tools; thinking config keys normalised",
    setPath(
      ["request", "tools"],
      [{ functionDeclarations: [{ name: "t", parametersJsonSchema: { type: "object" } }] }],
    ),
  ],
]);

/** Applies the case's request edit to its parsed golden request, when its golden predates the C6 port. */
export const portedRequestEdit = (key: string, expected: JsonObject): void => {
  const edit = REQUEST_EDITS.get(key);

  if (edit === undefined) return;
  const before = JSON.stringify(expected);
  edit(expected);

  if (JSON.stringify(expected) !== before) effectiveEdits.add(key);
};

/**
 * The edits (chunk and request) of this file's share of the cases that changed no golden: stale once the fixtures are
 * regenerated. `inScope` picks the keys this test file runs; the generated-id cases (`needs: ["id-normalization"]`) run in
 * `translator-fixtures-ids.test.ts`, the others in `translator-fixtures.test.ts`.
 */
export const staleGoldenEditEntries = (inScope: (key: string) => boolean): string[] =>
  [...CHUNK_EDITS.keys(), ...REQUEST_EDITS.keys()].filter(
    (key) => inScope(key) && !effectiveEdits.has(key),
  );
